import{_ as o,a0 as l,w as s,s as u,ao as a,I as r,a1 as i,A as n,x as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const h=JSON.parse('{"title":"在Linux上使用eCryptFS加密文件和目录 | LCTT x X-CMD","titleTemplate":false,"description":"在Linux上使用eCryptFS加密文件和目录 | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在Linux上使用eCryptFS加密文件和目录 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在Linux上使用eCryptFS加密文件和目录 | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141027 How to encrypt files and directories with eCryptFS on Linux","title":"在Linux上使用eCryptFS加密文件和目录","tag":"201412","desc":""},"relativePath":"201412/20141027 How to encrypt files and directories with eCryptFS on Linux.md","filePath":"[post].md"}'),d={name:"201412/20141027 How to encrypt files and directories with eCryptFS on Linux.md"};function f(y,t,C,m,S,x){const p=l("Link");return s(),u("div",null,[t[26]||(t[26]=a('<h1 id="在linux上使用ecryptfs加密文件和目录" tabindex="-1">在Linux上使用eCryptFS加密文件和目录 <a class="header-anchor" href="#在linux上使用ecryptfs加密文件和目录" aria-label="Permalink to “在Linux上使用eCryptFS加密文件和目录”">​</a></h1><p>作为罪犯，你需要为自己的身份保密；而作为中情局成员，你同样也需要为自己的身份保密。但是，你却不是他们其中的任何一员，你只是不想其他人查探到你的金融数据、家庭照片、尚未出版的手稿，或者记录着你能发家致富的最初想法的私密笔记。</p><p>我时常听到有人告诉我“我只是个微不足道的人，没人会查探我”或者“我没有什么东西要隐藏的。”好吧，告诉你我的想法，即便我没有什么要隐藏的，或者我也可以公开我带着狗的孩子的照片，那我也有权利不这么去做，也有权利来保护我的隐私。</p><h3 id="加密类型" tabindex="-1">加密类型 <a class="header-anchor" href="#加密类型" aria-label="Permalink to “加密类型”">​</a></h3><p>我们主要有两种加密文件和目录的方法。一种是文件系统级别的加密，在这种加密中，你可以选择性地加密某些文件或者目录（如，/home/alice）。对我而言，这是个十分不错的方法，你不需要为了启用或者测试加密而把所有一切重新安装一遍。然而，文件系统级别的加密也有一些缺点。例如，许多现代应用程序会缓存（部分）文件你硬盘中未加密的部分中，比如交换分区、/tmp和/var文件夹，而这会导致隐私泄漏。</p><p>另外一种方式，就是所谓的全盘加密，这意味着整个磁盘都会被加密（可能除了主引导记录外）。全盘加密工作在物理磁盘级别，写入到磁盘的每个比特都会被加密，而从磁盘中读取的任何东西都会在运行中解密。这会阻止任何潜在的对未加密数据的未经授权的访问，并且确保整个文件系统中的所有东西都被加密，包括交换分区或任何临时缓存数据。</p><h3 id="可用的加密工具" tabindex="-1">可用的加密工具 <a class="header-anchor" href="#可用的加密工具" aria-label="Permalink to “可用的加密工具”">​</a></h3><p>在Linux中要实施加密，有几个可供选择的工具。在本教程中，我打算介绍其中一个：<strong>eCryptFS</strong>，一个用户空间文件系统加密工具。下面提供了一个Linux上可用的加密工具摘要供您参考。</p><h4 id="文件系统级别加密" tabindex="-1">文件系统级别加密 <a class="header-anchor" href="#文件系统级别加密" aria-label="Permalink to “文件系统级别加密”">​</a></h4>',9)),r("ul",null,[r("li",null,[i(p,{href:"http://www.arg0.net/encfs"},{default:n(()=>[...t[0]||(t[0]=[e("EncFS",-1)])]),_:1}),t[1]||(t[1]=e("：尝试加密的最简单方式之一。EncFS工作在基于FUSE的伪文件系统上，所以你只需要创建一个加密文件夹并将它挂载到某个文件夹就可以工作了。",-1))]),r("li",null,[i(p,{href:"http://ecryptfs.org/"},{default:n(()=>[...t[2]||(t[2]=[e("eCryptFS",-1)])]),_:1}),t[3]||(t[3]=e("：一个POSIX兼容的加密文件系统，eCryptFS工作方式和EncFS相同，所以你必须挂载它。",-1))])]),t[27]||(t[27]=r("h4",{id:"磁盘级别加密",tabindex:"-1"},[e("磁盘级别加密 "),r("a",{class:"header-anchor",href:"#磁盘级别加密","aria-label":"Permalink to “磁盘级别加密”"},"​")],-1)),r("ul",null,[r("li",null,[i(p,{href:"http://sourceforge.net/projects/loop-aes/"},{default:n(()=>[...t[4]||(t[4]=[e("Loop-AES",-1)])]),_:1}),t[5]||(t[5]=e("：最古老的磁盘加密方法。它真的很快，并且适用于旧系统（如，2.0内核分支）。",-1))]),r("li",null,[i(p,{href:"https://code.google.com/p/cryptsetup/wiki/DMCrypt"},{default:n(()=>[...t[6]||(t[6]=[e("DMCrypt",-1)])]),_:1}),t[7]||(t[7]=e("：最常见的磁盘加密方案，支持现代Linux内核。",-1))]),r("li",null,[i(p,{href:"https://ciphershed.org/"},{default:n(()=>[...t[8]||(t[8]=[e("CipherShed",-1)])]),_:1}),t[9]||(t[9]=e("：已停止的TrueCrypt磁盘加密程序的一个开源分支。",-1))])]),t[28]||(t[28]=a(`<h3 id="ecryptfs基础" tabindex="-1">eCryptFS基础 <a class="header-anchor" href="#ecryptfs基础" aria-label="Permalink to “eCryptFS基础”">​</a></h3><p>eCrypFS是一个基于FUSE的用户空间加密文件系统，在Linux内核2.6.19及更高版本中可用（作为encryptfs模块）。eCryptFS加密的伪文件系统是挂载到当前文件系统顶部的。它可以很好地工作在EXT文件系统家族和其它文件系统如JFS、XFS、ReiserFS、Btrfs，甚至是NFS/CIFS共享文件系统上。Ubuntu使用eCryptFS作为加密其家目录的默认方法，ChromeOS也是。在eCryptFS底层，默认使用的是AES算法，但是它也支持其它算法，如blowfish、des3、cast5、cast6。如果你是通过手工创建eCryptFS设置，你可以选择其中一种算法。</p><p>就像我所的，Ubuntu让我们在安装过程中选择是否加密/home目录。好吧，这是使用eCryptFS的最简单的一种方法。</p><p><img src="https://farm6.staticflickr.com/5600/15639040345_8d74cd54a8_z.jpg" alt=""></p><p>Ubuntu提供了一个用户友好的工具集，通过eCryptFS可以让我们的生活更轻松，但是在Ubuntu安装过程中启用eCryptFS只创建了一个指定的预配置的设置。所以，如果默认的设置不适合你的需求，你需要进行手工设置。在本教程中，我将介绍<strong>如何在主流Linux发行版上手工设置eCryptFS</strong>。</p><h3 id="ecryptfs的安装" tabindex="-1">eCryptFS的安装 <a class="header-anchor" href="#ecryptfs的安装" aria-label="Permalink to “eCryptFS的安装”">​</a></h3><p>Debian，Ubuntu或其衍生版：</p><pre><code>$ sudo apt-get install ecryptfs-utils 
</code></pre><p>注意，如果你在Ubuntu安装过程中选择加密家目录，eCryptFS应该已经安装了。</p><p>CentOS, RHEL or Fedora：</p><pre><code># yum install ecryptfs-utils
</code></pre><p>Arch Linux：</p><pre><code>$ sudo pacman -S ecryptfs-utils
</code></pre><p>在安装完包后，加载eCryptFS内核模块当然会是一个很好的实践：</p><pre><code>$ sudo modprobe ecryptfs
</code></pre><h3 id="配置ecryptfs" tabindex="-1">配置eCryptFS <a class="header-anchor" href="#配置ecryptfs" aria-label="Permalink to “配置eCryptFS”">​</a></h3><p>现在，让我们开始加密一些目录，运行eCryptFS配置工具：</p><pre><code>$ ecryptfs-setup-private 
</code></pre><p><img src="https://farm6.staticflickr.com/5608/15453440890_3b4be6d5a7_z.jpg" alt=""></p><p>它会要求你输入登录密码和挂载密码。登录密码和你常规登录的密码一样，而挂载密码用于派生一个文件加密主密钥。这里留空可以生成一个（复杂的），这样会更安全。登出然后重新登录。</p><p>你会注意到，eCryptFS默认在你的家目录中创建了两个目录：Private和.Private。~/.Private目录包含有加密的数据，而你可以在~/Private目录中访问到相应的解密后的数据。在你登录时，~/.Private目录会自动解密并映射到~/Private目录，因此你可以访问它。当你登出时，~/Private目录会自动卸载，而~/Private目录中的内容会加密回到~/.Private目录。</p><p>eCryptFS怎么会知道你拥有~/.Private目录，并自动将其解密到~/Private目录而不需要我们输入密码呢？这就是eCryptFS的PAM模块捣的鬼，它为我们提供了这项便利服务。</p><p>如果你不想让~/Private目录在登录时自动挂载，只需要在运行ecryptfs-setup-private工具时添加“--noautomount”选项。同样，如果你不想要~/Private目录在登出后自动卸载，也可以自动“--noautoumount”选项。但是，那样后，你需要自己手工挂载或卸载~/Private目录：</p><pre><code>$ ecryptfs-mount-private ~/.Private ~/Private
$ ecryptfs-umount-private ~/Private
</code></pre><p>你可以来验证一下.Private文件夹是否被挂载，运行：</p><pre><code>$ mount 
</code></pre><p><img src="https://farm6.staticflickr.com/5610/15452374739_2ffb73cf05_z.jpg" alt=""></p><p>现在，我们可以开始把任何敏感文件放进~/Private文件夹里头了，它们会在我们登出时自动被加密并锁在~/.Private文件内。</p>`,28)),r("p",null,[t[11]||(t[11]=e("所有这一切看起来是那么得神奇。这主要是ecryptfs-setup-private工具让一切设置变得简单。如果你想要深究一点，对eCryptFS指定的方面进行设置，那么请转到",-1)),i(p,{href:"http://ecryptfs.org/documentation.html"},{default:n(()=>[...t[10]||(t[10]=[e("官方文档",-1)])]),_:1}),t[12]||(t[12]=e("。",-1))]),t[29]||(t[29]=r("h3",{id:"结尾",tabindex:"-1"},[e("结尾 "),r("a",{class:"header-anchor",href:"#结尾","aria-label":"Permalink to “结尾”"},"​")],-1)),t[30]||(t[30]=r("p",null,"综上所述，如果你十分关注你的隐私，最好是将基于eCryptFS文件系统级别的加密和全盘加密相结合。切记，只进行文件加密并不能保证你的隐私不受侵犯。",-1)),t[31]||(t[31]=r("hr",null,null,-1)),r("p",null,[t[14]||(t[14]=e("via: ",-1)),i(p,{href:"http://xmodulo.com/encrypt-files-directories-ecryptfs-linux.html"},{default:n(()=>[...t[13]||(t[13]=[e("http://xmodulo.com/encrypt-files-directories-ecryptfs-linux.html",-1)])]),_:1})]),r("p",null,[t[18]||(t[18]=e("作者：",-1)),i(p,{href:"http://xmodulo.com/author/valerio"},{default:n(()=>[...t[15]||(t[15]=[e("Christopher Valerio",-1)])]),_:1}),t[19]||(t[19]=e(" 译者：",-1)),i(p,{href:"https://github.com/GOLinux"},{default:n(()=>[...t[16]||(t[16]=[e("GOLinux",-1)])]),_:1}),t[20]||(t[20]=e(" 校对：",-1)),i(p,{href:"https://github.com/wxy"},{default:n(()=>[...t[17]||(t[17]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(p,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原创翻译，",-1)),i(p,{href:"http://linux.cn/"},{default:n(()=>[...t[22]||(t[22]=[e("Linux中国",-1)])]),_:1}),t[25]||(t[25]=e(" 荣誉推出",-1))])])}const b=o(d,[["render",f]]);export{h as __pageData,b as default};
